"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { CheckCircle, AlertCircle, Loader2, Edit, Trash2 } from "lucide-react";
import Layout from "../Layout"; // Adjust path to your Chef-specific Layout
import { useNavigate } from "react-router-dom";

export default function MainMeals() {
  const navigate = useNavigate();
  const [meals, setMeals] = useState([]);
  const [editingMeal, setEditingMeal] = useState(null);
  const [editFormData, setEditFormData] = useState({ mealName: "", priceOfMeal: "" });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const daysOfWeek = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  const mealTypes = ["Breakfast", "Lunch", "Dinner"];

  useEffect(() => {
    fetchMeals();
  }, []);

  const fetchMeals = async () => {
    try {
      setIsLoading(true);
      const token = localStorage.getItem("token");
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals/week`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.data.success) {
        setError(response.data.message || "Aucun repas trouvé pour cette semaine.");
        setMeals([]);
      } else {
        setMeals(response.data.meals || []);
        setSuccess(response.data.message || "Repas récupérés avec succès.");
      }
    } catch (error) {
      setError(error.response?.data?.message || "Erreur lors de la récupération des repas existants.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (meal) => {
    setEditingMeal(meal._id);
    setEditFormData({ mealName: meal.mealName, priceOfMeal: meal.priceOfMeal.toString() });
  };

  const handleSaveEdit = async (mealId) => {
    setIsSubmitting(true);
    try {
      const token = localStorage.getItem("token");
      const response = await axios.put(`${process.env.REACT_APP_API_URL}/api/meals/${mealId}`, editFormData, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.data.success) {
        setError(response.data.message || "Erreur lors de la modification du repas.");
      } else {
        setSuccess(response.data.message || "Repas modifié avec succès !");
        setEditingMeal(null);
        fetchMeals();
      }
    } catch (error) {
      setError(error.response?.data?.message || "Erreur lors de la modification du repas.");
      console.error('Update error:', error.response?.data); // Log detailed error
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (mealId) => {
    console.log('Attempting to delete meal with ID:', mealId); // Add logging
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce repas ?")) {
      setIsSubmitting(true);
      try {
        const token = localStorage.getItem("token");
        const response = await axios.delete(`${process.env.REACT_APP_API_URL}/api/meals/${mealId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (!response.data.success) {
          setError(response.data.message || "Erreur lors de la suppression du repas.");
        } else {
          setSuccess(response.data.message || "Repas supprimé avec succès !");
          fetchMeals();
        }
      } catch (error) {
        setError(error.response?.data?.message || "Erreur lors de la suppression du repas.");
        console.error('Delete error:', error.response?.data); // Log detailed error
      } finally {
        setIsSubmitting(false);
      }
    }
  };

  const handleCancelEdit = () => {
    setEditingMeal(null);
    setEditFormData({ mealName: "", priceOfMeal: "" });
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEditFormData((prev) => ({ ...prev, [name]: value }));
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fr-FR', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Gestion des repas de la semaine</h2>
            <p className="text-white/80 mt-1">Affichez et gérez les repas pour la semaine en cours (Lundi à Dimanche)</p>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-48">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des repas...</p>
              </div>
            </div>
          ) : (
            <div className="p-6">
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Date</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Jour</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Type</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nom du repas</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Prix (DH)</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {meals.length === 0 && !isLoading ? (
                      <tr>
                        <td colSpan="6" className="px-4 py-4 text-center text-gray-500">
                          {error || "Aucun repas trouvé pour cette semaine."}
                        </td>
                      </tr>
                    ) : (
                      meals.map((meal) => (
                        <tr key={meal._id} className="hover:bg-gray-50">
                          <td className="px-4 py-2 whitespace-nowrap">
                            {formatDate(meal.date)}
                          </td>
                          <td className="px-4 py-2 whitespace-nowrap">
                            {daysOfWeek[new Date(meal.date).getDay()]}
                          </td>
                          <td className="px-4 py-2 whitespace-nowrap">{meal.type}</td>
                          <td className="px-4 py-2 whitespace-nowrap">
                            {editingMeal === meal._id ? (
                              <input
                                type="text"
                                name="mealName"
                                value={editFormData.mealName}
                                onChange={handleChange}
                                className="w-full px-2 py-1 border border-gray-300 rounded-md focus:ring-[#00717F] focus:border-[#00717F]"
                                required
                              />
                            ) : (
                              meal.mealName
                            )}
                          </td>
                          <td className="px-4 py-2 whitespace-nowrap">
                            {editingMeal === meal._id ? (
                              <input
                                type="number"
                                name="priceOfMeal"
                                value={editFormData.priceOfMeal}
                                onChange={handleChange}
                                className="w-full px-2 py-1 border border-gray-300 rounded-md focus:ring-[#00717F] focus:border-[#00717F]"
                                required
                                min="0"
                                step="0.01"
                              />
                            ) : (
                              `${meal.priceOfMeal} DH`
                            )}
                          </td>
                          <td className="px-4 py-2 whitespace-nowrap">
                            {editingMeal === meal._id ? (
                              <>
                                <button
                                  onClick={() => handleSaveEdit(meal._id)}
                                  disabled={isSubmitting}
                                  className="text-green-600 hover:text-green-800 mr-2"
                                >
                                  <CheckCircle className="h-5 w-5" />
                                </button>
                                <button
                                  onClick={handleCancelEdit}
                                  className="text-gray-600 hover:text-gray-800"
                                >
                                  Annuler
                                </button>
                              </>
                            ) : (
                              <>
                                <button
                                  onClick={() => handleEdit(meal)}
                                  className="text-blue-600 hover:text-blue-800 mr-2"
                                >
                                  <Edit className="h-5 w-5" />
                                </button>
                                <button
                                  onClick={() => handleDelete(meal._id)}
                                  className="text-red-600 hover:text-red-800"
                                >
                                  <Trash2 className="h-5 w-5" />
                                </button>
                              </>
                            )}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}
